export function getSkillBySlug(slug: string): SkillItem | undefined {
  return SKILLS_CATALOG.find((item) => item.slug === slug);
}

export function getKindTabCounts() {
  const counts = {
    "visual-skill": 0,
    "browser-tool": 0,
    "text-workflow": 0,
    "agent-workflow": 0,
    all: SKILLS_CATALOG.length,
    featured: 0,
  };
  for (const item of SKILLS_CATALOG) {
    counts[item.kind] += 1;
    if (item.featured) counts.featured += 1;
  }
  return counts;
}

export function getTopicCounts(): Record<TopicSlug, number> {
  const counts = Object.fromEntries(
    TOPIC_ITEMS.map((t) => [t.slug, 0])
  ) as Record<TopicSlug, number>;
  for (const item of SKILLS_CATALOG) {
    for (const topic of item.topics) {
      counts[topic] = (counts[topic] ?? 0) + 1;
    }
  }
  return counts;
}

export function getOutputCounts(): Record<OutputType, number> {
  const counts: Record<OutputType, number> = {
    images: 0,
    video: 0,
    slides: 0,
    web: 0,
    games: 0,
  };
  for (const item of SKILLS_CATALOG) {
    if (item.output) {
      counts[item.output] = (counts[item.output] ?? 0) + 1;
    }
  }
  return counts;
}

export function getTaskCounts(): Record<TaskToolType, number> {
  const counts: Record<TaskToolType, number> = {
    data: 0,
    developer: 0,
    writing: 0,
  };
  for (const item of SKILLS_CATALOG) {
    if (item.taskTool) {
      counts[item.taskTool] = (counts[item.taskTool] ?? 0) + 1;
    }
  }
  return counts;
}

export function querySkills(input: SkillQueryInput): SkillItem[] {
  const q = (input.q ?? "").trim().toLowerCase();
  const filtered = SKILLS_CATALOG.filter((item) => {
    if (input.kind && input.kind !== "all") {
      if (input.kind === "featured") {
        if (!item.featured) return false;
      } else if (item.kind !== input.kind) {
        return false;
      }
    }
    if (
      input.collection &&
      input.collection !== "all" &&
      !item.collections.includes(input.collection)
    ) {
      return false;
    }
    if (input.output && input.output !== "all" && item.output !== input.output) {
      return false;
    }
    if (input.task && input.task !== "all" && item.taskTool !== input.task) {
      return false;
    }
    if (input.topic && input.topic !== "all" && !item.topics.includes(input.topic)) {
      return false;
    }
    if (
      input.platform &&
      input.platform !== "all" &&
      !item.platforms.includes(input.platform)
    ) {
      return false;
    }
    if (input.freeOnly && !item.free) {
      return false;
    }
    if (input.testedOnly && !item.functionTested) {
      return false;
    }
    if (q) {
      const haystack = [
        item.title,
        item.englishName,
        item.summary,
        item.repo,
        ...item.techTags,
      ]
        .join(" ")
        .toLowerCase();
      if (!haystack.includes(q)) {
        return false;
      }
    }
    return true;
  });

  const sortMode = input.sort ?? "newest";
  return [...filtered].sort((a, b) => {
    if (sortMode === "popular") {
      return b.stars - a.stars;
    }
    if (sortMode === "oldest") {
      return a.updatedAt.localeCompare(b.updatedAt);
    }
    if (sortMode === "type") {
      return a.kind.localeCompare(b.kind);
    }
    if (sortMode === "name-asc") {
      return a.title.localeCompare(b.title, "zh-CN");
    }
    if (sortMode === "name-desc") {
      return b.title.localeCompare(a.title, "zh-CN");
    }
    return b.updatedAt.localeCompare(a.updatedAt) || b.stars - a.stars;
  });
}

export function getCatalogStats() {
  const counts = getKindTabCounts();
  return {
    totalItems: counts.all,
    visualCount: counts["visual-skill"],
    browserCount: counts["browser-tool"],
    workflowCount: counts["text-workflow"] + counts["agent-workflow"],
  };
}
